// Validate the Pi relay request before touching alert-store.
// If requests are rejected here, check X-Relay-Token and required alert fields.
const expectedToken = $vars.RELAY_WEBHOOK_TOKEN || 'REPLACE_WITH_RELAY_TOKEN';
const headers = $json.headers || {};
const body = $json.body || $json;
const token = headers['x-relay-token'] || headers['X-Relay-Token'];
const errors = [];
const isHeartbeat = body?.message_type === 'relay_heartbeat';

if (token !== expectedToken) {
  errors.push('invalid or missing X-Relay-Token');
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('body must be a JSON object');
}

if (!isHeartbeat) {
  const requiredFields = ['alert_id', 'timestamp', 'rule_name', 'event_dataset'];
  for (const field of requiredFields) {
    if (!body[field]) errors.push(`missing ${field}`);
  }

  const hasSourceIp = Boolean(body.source && body.source.ip);
  const hasDestinationIp = Boolean(body.destination && body.destination.ip);
  if (!hasSourceIp && !hasDestinationIp) {
    errors.push('missing source.ip or destination.ip');
  }
}

if (errors.length > 0) {
  return [{
    json: {
      ok: false,
      status: 'rejected',
      stage: 'validate-relay-request',
      reason: errors.join('; '),
      alert_id: body?.alert_id || null,
      rule_name: body?.rule_name || body?.first_rule || null,
      event_dataset: body?.event_dataset || null,
      source_ip: body?.source?.ip || null,
      destination_ip: body?.destination?.ip || null,
      received_at: (() => { const date = new Date(); const pad = (value, length = 2) => String(value).padStart(length, '0'); const offsetMinutes = -date.getTimezoneOffset(); const sign = offsetMinutes >= 0 ? '+' : '-'; const absolute = Math.abs(offsetMinutes); const offset = `${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`; return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}  ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${offset}`; })(),
    }
  }];
}

return [{
  json: {
    ok: true,
    status: isHeartbeat ? 'validated_heartbeat' : 'validated',
    stage: 'validate-relay-request',
    alert: body,
    alert_id: body.alert_id || null,
    rule_name: body.rule_name || body.first_rule || (isHeartbeat ? 'relay heartbeat' : null),
    event_dataset: body.event_dataset || (isHeartbeat ? 'relay.heartbeat' : null),
    source_ip: body.source?.ip || null,
    destination_ip: body.destination?.ip || null,
    received_at: (() => { const date = new Date(); const pad = (value, length = 2) => String(value).padStart(length, '0'); const offsetMinutes = -date.getTimezoneOffset(); const sign = offsetMinutes >= 0 ? '+' : '-'; const absolute = Math.abs(offsetMinutes); const offset = `${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`; return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}  ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${offset}`; })(),
  }
}];

// Send one validated alert to alert-store for scoring, dedupe, drop, and suppression.
// If this node fails, check the alert-store container and /health endpoint first.
const http = require('http');
const {URL} = require('url');
const alertStoreUrl = 'http://alert-store:8787/alert';

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const data = JSON.stringify(payload);
    const req = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 80,
        path: `${parsed.pathname}${parsed.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(data),
        },
        timeout: 30000,
      },
      (res) => {
        let responseBody = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => responseBody += chunk);
        res.on('end', () => resolve({statusCode: res.statusCode, body: responseBody}));
      },
    );
    req.on('timeout', () => req.destroy(new Error('alert-store request timed out')));
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

if (!$json.ok) {
  return [{json: {...$json, stage: 'store-score-filter-alert', stored: false}}];
}

const alertForStore = $json.alert || {};
let store;
try {
  const response = await postJson(alertStoreUrl, alertForStore);
  try {
    store = JSON.parse(response.body);
  } catch (error) {
    throw new Error(`alert-store returned non-JSON response: ${response.body.slice(0, 200)}`);
  }
  if (response.statusCode < 200 || response.statusCode >= 300 || !store.ok) {
    throw new Error(`alert-store rejected alert: ${store.reason || response.statusCode}`);
  }
} catch (error) {
  throw new Error(`alert-store unavailable: ${error.message}`);
}

const storedAlert = store.alert || {};
const triage = store.triage || {};
const filter = store.filter || {status: store.status || 'unknown'};
const notification = store.notification || {status: 'unknown'};
const status = store.status;
const routing = status === 'already_seen' ? 'duplicate-suppressed' : (triage.routing || storedAlert.routing || 'unknown');

return [{
  json: {
    ok: true,
    stage: 'store-score-filter-alert',
    status,
    stored: Boolean(store.stored),
    original_alert: alertForStore,
    alert_id: storedAlert.alert_id || alertForStore.alert_id,
    rule_name: storedAlert.rule_name || alertForStore.rule_name || null,
    event_dataset: storedAlert.event_dataset || alertForStore.event_dataset || null,
    severity: storedAlert.severity ?? alertForStore.severity ?? null,
    severity_label: storedAlert.severity_label || alertForStore.severity_label || null,
    source_ip: storedAlert.source_ip || alertForStore.source?.ip || null,
    destination_ip: storedAlert.destination_ip || alertForStore.destination?.ip || null,
    traffic_direction: triage.traffic_direction || storedAlert.traffic_direction || null,
    triage_score: triage.score ?? storedAlert.triage_score ?? null,
    triage_level: triage.level || storedAlert.triage_level || null,
    routing,
    triage_reasons: triage.reasons || [],
    filter_status: filter.status || storedAlert.filter_status || null,
    filter_reason: filter.reason || storedAlert.filter_reason || null,
    suppression_key: filter.key || storedAlert.suppression_key || null,
    suppression_rule: filter.rule || null,
    suppression_ttl_seconds: filter.ttl_seconds || null,
    suppression_seen_count: filter.seen_count || null,
    notification_channel: notification.channel || 'telegram',
    notification_status: notification.status,
    notification_cooldown_seconds: notification.cooldown_seconds || null,
    first_seen: storedAlert.first_seen || null,
    last_seen: storedAlert.last_seen || null,
    seen_count: storedAlert.seen_count || null,
    received_at: (() => { const date = new Date(); const pad = (value, length = 2) => String(value).padStart(length, '0'); const offsetMinutes = -date.getTimezoneOffset(); const sign = offsetMinutes >= 0 ? '+' : '-'; const absolute = Math.abs(offsetMinutes); const offset = `${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`; return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}  ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${offset}`; })(),
  }
}];

// Convert alert-store status into a simple report-write decision for the next node.
// Dropped, suppressed, and duplicate alerts remain in SQLite but skip Markdown.
if (!$json.ok) {
  return [{json: {...$json, stage: 'route-report-decision', should_write_report: false, report_skip_reason: $json.reason || 'invalid_request'}}];
}

const shouldWriteReport = $json.status === 'accepted';
let reportSkipReason = null;
if (!shouldWriteReport) {
  if ($json.status === 'dropped') reportSkipReason = 'dropped_by_policy';
  else if ($json.status === 'suppressed') reportSkipReason = 'suppressed_repeat';
  else if ($json.status === 'already_seen') reportSkipReason = 'duplicate_alert_id';
  else reportSkipReason = `status_${$json.status || 'unknown'}`;
}

return [{
  json: {
    ...$json,
    stage: 'route-report-decision',
    should_write_report: shouldWriteReport,
    report_decision: shouldWriteReport ? 'write_markdown_report' : 'skip_markdown_report',
    report_skip_reason: reportSkipReason,
  }
}];

// Write one deterministic Markdown report for a durably committed alert.
// The dashboard reads SQLite; this file remains the local LLM/Obsidian corpus.
const fs = require('fs');
const path = require('path');
const reportDir = '/soc-alerts';

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return null;
}

function localTimestamp() {
  const date = new Date();
  const pad = (value, length = 2) => String(value).padStart(length, '0');
  const offsetMinutes = -date.getTimezoneOffset();
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const absolute = Math.abs(offsetMinutes);
  const offset = `${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`;
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}  ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${offset}`;
}

function safePart(value, limit = 90) {
  const cleaned = String(value || 'unknown')
    .replace(/[^A-Za-z0-9_.-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return (cleaned || 'unknown').slice(0, limit);
}

function stableReportPart(item) {
  const value = String(item.report_job_id || item.alert_id || 'alert');
  // Security Onion IDs share long prefixes; retain the unique tail when a
  // bounded filename is needed.
  return safePart(value.length > 72 ? value.slice(-72) : value, 72);
}

function md(value) {
  if (Array.isArray(value)) return value.join(', ');
  if (value && typeof value === 'object') return JSON.stringify(value);
  return value === undefined || value === null || value === '' ? 'n/a' : String(value);
}

function cell(value) {
  return md(value).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

function table(rows) {
  const out = ['| Field | Value |', '| --- | --- |'];
  for (const [key, value] of rows) out.push(`| ${cell(key)} | ${cell(value)} |`);
  return out.join('\n');
}

function renderReport(item) {
  const originalAlert = item.original_alert || {};
  const alertId = firstValue(item.alert_id, originalAlert.alert_id);
  const ruleName = firstValue(item.rule_name, originalAlert.rule_name, 'Security Onion Alert');
  const level = String(firstValue(item.triage_level, item.severity_label, originalAlert.severity_label, 'unknown')).toUpperCase();
  const score = item.triage_score;
  const routing = firstValue(item.routing, 'unknown');
  const sourceIp = firstValue(item.source_ip, originalAlert.source?.ip);
  const sourcePort = firstValue(originalAlert.source?.port);
  const destIp = firstValue(item.destination_ip, originalAlert.destination?.ip);
  const destPort = firstValue(originalAlert.destination?.port);
  const direction = item.traffic_direction;
  const reasons = Array.isArray(item.triage_reasons) && item.triage_reasons.length
    ? item.triage_reasons
    : ['No scoring reasons returned by alert-store.'];
  // The commit timestamp is stable across retries, so rewriting the same job
  // produces byte-for-byte equivalent report metadata.
  const generatedAt = firstValue(item.committed_at, localTimestamp());

  const lines = [];
  lines.push('---');
  lines.push('type: soc-alert-report');
  lines.push(`generated_at: ${generatedAt}`);
  lines.push(`alert_id: ${JSON.stringify(alertId || '')}`);
  lines.push(`triage_level: ${JSON.stringify(level.toLowerCase())}`);
  lines.push(`triage_score: ${score ?? ''}`);
  lines.push(`status: ${JSON.stringify(item.status || '')}`);
  lines.push(`filter_status: ${JSON.stringify(item.filter_status || '')}`);
  lines.push(`source_ip: ${JSON.stringify(sourceIp || '')}`);
  lines.push(`destination_ip: ${JSON.stringify(destIp || '')}`);
  lines.push('tags:');
  lines.push('  - security-onion');
  lines.push('  - soc-alert');
  lines.push('  - n8n-generated');
  lines.push('---');
  lines.push('');
  lines.push(`# [${level}] ${ruleName}`);
  lines.push('');
  lines.push(`- **Generated:** ${generatedAt}`);
  lines.push(`- **Alert ID:** ${md(alertId)}`);
  lines.push(`- **Workflow status:** ${md(item.status)}`);
  lines.push(`- **Filter status:** ${md(item.filter_status)}`);
  lines.push(`- **Route:** ${md(routing)}`);
  lines.push(`- **Score:** ${md(score)}`);
  lines.push(`- **Direction:** ${md(direction)}`);
  lines.push(`- **Traffic:** ${md(sourceIp)}${sourcePort ? ':' + sourcePort : ''} -> ${md(destIp)}${destPort ? ':' + destPort : ''}`);
  lines.push('');
  lines.push('## Triage Reasons');
  lines.push('');
  for (const reason of reasons) lines.push(`- [ ] ${md(reason)}`);
  lines.push('');
  lines.push('## Alert Summary');
  lines.push('');
  lines.push(table([
    ['Rule name', ruleName],
    ['Event dataset', item.event_dataset],
    ['Severity', item.severity],
    ['Severity label', item.severity_label],
    ['Rule category', originalAlert.rule_category],
    ['Timestamp', originalAlert.timestamp],
    ['First seen', item.first_seen],
    ['Last seen', item.last_seen],
    ['Seen count', item.seen_count],
    ['Filter status', item.filter_status],
    ['Filter reason', item.filter_reason],
    ['Suppression rule', item.suppression_rule],
    ['Telegram notification', item.notification_status],
  ]));
  lines.push('');
  lines.push('## Analyst Notes');
  lines.push('');
  lines.push('- [ ] Confirm whether source and destination are expected for this VLAN or host role.');
  lines.push('- [ ] Pivot in Security Onion for related source, destination, DNS, HTTP, TLS, and connection events.');
  lines.push('- [ ] Decide whether this should become a tuning rule, an escalation, or a documented benign pattern.');
  lines.push('');
  lines.push('## Raw Alert');
  lines.push('');
  lines.push('```json');
  lines.push(JSON.stringify(originalAlert, null, 2));
  lines.push('```');
  lines.push('');
  return lines.join('\n');
}

if (!$json.should_write_report) {
  return [{json: {
    ...$json,
    stage: 'write-soc-markdown-report',
    report_written: false,
    report_path: null,
    report_filename: null,
  }}];
}

fs.mkdirSync(reportDir, {recursive: true});
const filenameTimestamp = String(firstValue($json.committed_at, localTimestamp()))
  .replace(/[-:]/g, '')
  .replace(/\s+/, '-')
  .replace('Z', 'Z');
const filename = `${filenameTimestamp}-${safePart($json.triage_level)}-${stableReportPart($json)}-${safePart($json.rule_name)}.md`;
const fullPath = path.join(reportDir, filename);
const temporaryPath = `${fullPath}.tmp`;
fs.writeFileSync(temporaryPath, renderReport($json), 'utf8');
fs.renameSync(temporaryPath, fullPath);

return [{json: {
  ...$json,
  stage: 'write-soc-markdown-report',
  report_written: true,
  report_path: fullPath,
  report_filename: filename,
}}];

// Enrichment is queued durably by alert-store in the same SQLite transaction
// that stores the alert. Keep this explicit n8n stage as a fast, observable
// handoff without making webhook latency depend on public APIs.
if (!$json.ok || !$json.alert) {
  return [{json: {...$json, stage: 'queue-enrichment', enrichment_status: 'skipped_validation_failed'}}];
}
return [{json: {...$json, stage: 'queue-enrichment', enrichment_status: 'queued_by_alert_store'}}];

// Authenticate post-commit work before n8n touches the Markdown corpus.
// alert-store owns retries, so rejected payloads return a structured result
// that leaves the durable job pending instead of silently losing work.
const expectedToken = String($vars.RELAY_WEBHOOK_TOKEN || '').trim();
const headers = $json.headers || {};
const body = $json.body || $json;
const suppliedToken = String(headers['x-relay-token'] || headers['X-Relay-Token'] || '').trim();
const errors = [];

if (!expectedToken || expectedToken === 'REPLACE_WITH_RELAY_TOKEN') {
  errors.push('RELAY_WEBHOOK_TOKEN is not configured in n8n');
} else if (suppliedToken !== expectedToken) {
  errors.push('invalid or missing X-Relay-Token');
}
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('body must be a JSON object');
} else {
  if (!body.alert_id) errors.push('missing alert_id');
  if (!body.report_job_id) errors.push('missing report_job_id');
  if (!body.committed_at) errors.push('missing committed_at');
  if (!body.original_alert || typeof body.original_alert !== 'object' || Array.isArray(body.original_alert)) {
    errors.push('missing original_alert object');
  }
  if (body.should_write_report !== true) errors.push('should_write_report must be true');
}

if (errors.length) {
  return [{json: {
    ok: false,
    status: 'rejected',
    stage: 'validate-committed-alert',
    reason: errors.join('; '),
    alert_id: body?.alert_id || null,
    report_written: false,
  }}];
}

return [{json: {
  ...body,
  ok: true,
  status: body.status || 'accepted',
  stage: 'validate-committed-alert',
}}];

// The legacy/rollback webhook still validates and commits alerts through
// alert-store, but Markdown generation is intentionally deferred to the
// durable post-commit queue. This response keeps relay acknowledgement fast.
return [{json: {
  ...$json,
  stage: 'acknowledge-durable-alert-commit',
  report_written: false,
  report_deferred_to_post_commit: $json.status === 'accepted',
}}];
